import sys

data = sys.stdin.read().split()
n = int(data[0])
arr = [int(x) for x in data[1:1 + n]]
MOD = 10**9 + 7
fixed = [x for x in arr if x != 0]
lo = min(fixed) - n - 1
hi = max(fixed) + n + 1
dp = {}
for v in range(lo, hi + 1):
    if arr[0] == 0 or arr[0] == v:
        dp[v] = 1
for i in range(1, n):
    nd = {}
    for v in range(lo, hi + 1):
        if arr[i] != 0 and arr[i] != v:
            continue
        s = dp.get(v - 1, 0) + dp.get(v, 0) + dp.get(v + 1, 0)
        if s:
            nd[v] = s
    dp = nd
print(sum(dp.values()) % MOD)

